// src/pages/AIWrite.js

import { useState } from "react";

import {
  FiSearch,
  FiCamera,
} from "react-icons/fi";

import { createReview } from "../api/api";

import Tesseract from "tesseract.js";


function AIWrite() {

  // ==================================================
  // 책 검색
  // ==================================================

  const [searched, setSearched] =
    useState(false);


  // ==================================================
  // 책 선택
  // ==================================================

  const [selected, setSelected] =
    useState(false);


  // ==================================================
  // AI 독후감 생성
  // ==================================================

  const [generated, setGenerated] =
    useState(false);


  // ==================================================
  // AI 독후감 생성 중
  // ==================================================

  const [loading, setLoading] =
    useState(false);


  // ==================================================
  // OCR 진행 중
  // ==================================================

  const [ocrLoading, setOcrLoading] =
    useState(false);


  // ==================================================
  // 에러
  // ==================================================

  const [error, setError] =
    useState("");


  // ==================================================
  // 인상 깊은 구절
  // ==================================================

  const [quote, setQuote] =
    useState("");


  // ==================================================
  // 느낀점
  // ==================================================

  const [reflection, setReflection] =
    useState("");


  // ==================================================
  // 여러 사진
  // ==================================================

  const [images, setImages] =
    useState([]);


  // ==================================================
  // 여러 사진의 OCR 결과
  // ==================================================

  const [ocrText, setOcrText] =
    useState("");


  // ==================================================
  // AI 독후감 결과
  // ==================================================

  const [generatedReview, setGeneratedReview] =
    useState("");


  // ==================================================
  // 선택된 책
  //
  // 현재는 기존 더미데이터
  // ==================================================

  const selectedBook = {
    title: "노르웨이의 숲",
    author: "무라카미 하루키",
  };


  // ==================================================
  // 책 검색
  // ==================================================

  const handleSearch = () => {

    setSearched(true);

  };


  // ==================================================
  // 책 선택
  // ==================================================

  const handleSelectBook = () => {

    setSelected(true);

    setSearched(false);

  };


  // ==================================================
  // Tesseract.js OCR
  // ==================================================
  //
  // 사진 하나를 받아서 OCR 실행
  //
  // 여러 사진이 들어오면 각각 실행됨
  // ==================================================

  const runOCR = async (file) => {

    try {

      console.log(
        "Tesseract.js OCR 시작:",
        file.name
      );


      const result =
        await Tesseract.recognize(
          file,
          "kor+eng",
          {
            logger: (info) => {

              console.log(
                "OCR 진행:",
                info
              );

            },
          }
        );


      const text =
        result.data.text.trim();


      console.log(
        "OCR 결과:",
        text
      );


      // ==================================================
      // 여러 사진의 OCR 결과를 누적
      // ==================================================

      if (text) {

        setOcrText((prev) => {

          if (!prev.trim()) {
            return text;
          }

          return `${prev}\n\n${text}`;

        });

      }


      return text;

    } catch (err) {

      console.error(
        "OCR 실패:",
        err
      );


      return "";

    }

  };


  // ==================================================
  // 사진 추가
  // ==================================================
  //
  // 여러 장 선택 가능
  // + 여러 번 추가 가능
  // ==================================================

  const handleImageChange = async (
    event
  ) => {

    const files =
      Array.from(
        event.target.files || []
      );


    if (files.length === 0) {
      return;
    }


    setError("");

    setOcrLoading(true);


    // ==================================================
    // 사진 화면에 추가
    // ==================================================

    const newImages =
      files.map((file) => ({

        id:
          `${file.name}-${file.lastModified}-${Math.random()}`,

        url:
          URL.createObjectURL(file),

        name:
          file.name,

      }));


    setImages((prev) => [

      ...prev,

      ...newImages,

    ]);


    // ==================================================
    // 선택한 모든 사진 OCR
    // ==================================================

    try {

      for (
        const file of files
      ) {

        await runOCR(file);

      }

    } catch (err) {

      console.error(
        "여러 사진 OCR 실패:",
        err
      );

      setError(
        "사진의 텍스트를 읽는 중 문제가 발생했어요."
      );

    } finally {

      setOcrLoading(false);

    }


    // ==================================================
    // 같은 사진을 다시 선택할 수 있도록 초기화
    // ==================================================

    event.target.value = "";

  };


  // ==================================================
  // 사진 삭제
  // ==================================================

  const handleRemoveImage = (
    imageId
  ) => {

    setImages((prev) =>
      prev.filter(
        (image) =>
          image.id !== imageId
      )
    );

  };


  // ==================================================
  // AI 독후감 생성
  // ==================================================

  const handleGenerate = async () => {

    if (loading) {
      return;
    }


    // ==================================================
    // 책 선택 확인
    // ==================================================

    if (!selected) {

      setError(
        "먼저 책을 선택해주세요."
      );

      return;

    }


    // ==================================================
    // 느낀점 확인
    // ==================================================

    if (!reflection.trim()) {

      setError(
        "느낀점을 작성해주세요."
      );

      return;

    }


    setError("");

    setLoading(true);

    setGenerated(false);


    // ==================================================
    // ★ 백엔드로 보낼 데이터
    // ==================================================
    //
    // 1. 책 정보
    // 2. 사진에서 추출한 OCR 텍스트
    // 3. 직접 작성한 인상 깊은 구절
    // 4. 직접 작성한 느낀점
    //
    // ==================================================

    const requestData = {

      book: {

        title:
          selectedBook.title,

        author:
          selectedBook.author,

      },


      // 여러 사진에서 추출된 OCR 결과

      ocrText:
        ocrText.trim(),


      // 직접 작성한 구절

      quote:
        quote.trim(),


      // 직접 작성한 느낀점

      reflection:
        reflection.trim(),

    };


    console.log(
      "백엔드로 보내는 데이터:",
      requestData
    );


    try {

      // ==================================================
      // ★ Backend API 호출
      // ==================================================

      const data =
        await createReview(
          requestData
        );


      console.log(
        "백엔드 응답:",
        data
      );


      // ==================================================
      // 백엔드에서 받은 AI 독후감
      // ==================================================

      const review =
        data.review ||
        data.generatedReview ||
        data.content ||
        "AI 독후감이 생성되었습니다.";


      setGeneratedReview(
        review
      );


      setGenerated(true);

    } catch (err) {

      console.error(
        "AI 독후감 생성 실패:",
        err
      );


      setError(
        "AI 독후감 생성에 실패했어요. 백엔드 연결을 확인해주세요."
      );

    } finally {

      setLoading(false);

    }

  };


  // ==================================================
  // 화면
  // ==================================================

  return (

    <div className="page">


      {/* ==================================================
          상단
      ================================================== */}

      <div className="top-bar">

        <div className="logo">
          READLY
        </div>

      </div>


      <div className="line"></div>


      {/* ==================================================
          제목
      ================================================== */}

      <div className="write-top">

        <div className="write-title">
          AI 독후감 작성
        </div>

        <div className="write-sub">
          책과 감상을 기록해보세요
        </div>

      </div>


      {/* ==================================================
          책 검색
      ================================================== */}

      <div className="write-card">

        <div className="input-label">
          어떤 책을 읽었나요?
        </div>


        <div className="book-search">

          <FiSearch />


          <input
            placeholder="책 제목 검색하기"
            onChange={handleSearch}
          />

        </div>


        {/* ==================================================
            검색 결과
        ================================================== */}

        {searched && !selected && (

          <div
            className="search-item"
            onClick={handleSelectBook}
          >

            <div className="search-cover">
              📘
            </div>


            <div>

              <div className="book-name">
                노르웨이의 숲
              </div>


              <div className="book-author">
                무라카미 하루키
              </div>

            </div>

          </div>

        )}


        {/* ==================================================
            선택된 책
        ================================================== */}

        {selected && (

          <div className="book-result">

            <div className="book-cover">
              📘
            </div>


            <div>

              <div className="book-name">
                {selectedBook.title}
              </div>


              <div className="book-author">
                {selectedBook.author}
              </div>

            </div>

          </div>

        )}

      </div>


      {/* ==================================================
          인상 깊은 구절
      ================================================== */}

      <div className="write-card">

        <div className="input-label">
          인상 깊은 구절
        </div>


        <textarea
          className="write-textarea"
          placeholder="기억에 남는 문장을 적어보세요"
          value={quote}
          onChange={(e) =>
            setQuote(
              e.target.value
            )
          }
        />


        {/* ==================================================
            사진 추가
        ================================================== */}

        <label
          className="photo-btn"
          style={{
            cursor:
              ocrLoading
                ? "default"
                : "pointer",
          }}
        >

          <FiCamera />

          {ocrLoading
            ? "텍스트를 읽고 있어요..."
            : "책 구절 사진 추가하기"}


          <input
            type="file"
            accept="image/*"
            capture="environment"
            multiple
            onChange={handleImageChange}
            disabled={ocrLoading}
            style={{
              display: "none",
            }}
          />

        </label>


        {/* ==================================================
            추가된 사진들
        ================================================== */}

        {images.length > 0 && (

          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: "12px",
              marginTop: "14px",
            }}
          >

            {images.map((image) => (

              <div
                key={image.id}
                style={{
                  position: "relative",
                }}
              >

                <img
                  src={image.url}
                  alt="책 구절"
                  style={{
                    width: "100%",
                    maxHeight: "300px",
                    objectFit: "contain",
                    borderRadius: "12px",
                    display: "block",
                  }}
                />


                {/* 사진 삭제 버튼 */}

                <button
                  type="button"
                  onClick={() =>
                    handleRemoveImage(
                      image.id
                    )
                  }
                  style={{
                    position: "absolute",
                    top: "8px",
                    right: "8px",
                    width: "28px",
                    height: "28px",
                    border: "none",
                    borderRadius: "50%",
                    background:
                      "rgba(0,0,0,0.55)",
                    color: "#ffffff",
                    fontSize: "16px",
                    cursor: "pointer",
                  }}
                >
                  ×
                </button>

              </div>

            ))}

          </div>

        )}


        {/* ==================================================
            OCR 결과
        ================================================== */}

        {ocrText && (

          <div
            style={{
              marginTop: "14px",
              padding: "12px",
              background:
                "#f7f9f1",
              borderRadius: "10px",
              fontSize: "13px",
              lineHeight: "1.6",
              whiteSpace: "pre-line",
            }}
          >

            <div
              style={{
                fontWeight: "700",
                marginBottom: "6px",
              }}
            >
              📷 사진에서 추출된 구절
            </div>


            {ocrText}

          </div>

        )}

      </div>


      {/* ==================================================
          느낀점
      ================================================== */}

      <div className="write-card">

        <div className="input-label">
          느낀점
        </div>


        <textarea
          className="write-textarea big"
          placeholder="책을 읽고 어떤 생각이 들었나요?"
          value={reflection}
          onChange={(e) =>
            setReflection(
              e.target.value
            )
          }
        />

      </div>


      {/* ==================================================
          에러
      ================================================== */}

      {error && (

        <div
          style={{
            margin:
              "0 16px 12px",
            padding: "10px",
            background:
              "#fff0f0",
            borderRadius: "10px",
            color:
              "#d95353",
            fontSize: "13px",
          }}
        >
          {error}
        </div>

      )}


      {/* ==================================================
          AI 독후감 생성 버튼
      ================================================== */}

      <button
        className="generate-btn"
        type="button"
        onClick={handleGenerate}
        disabled={loading}
      >

        {loading
          ? "✨ AI가 독후감을 작성하고 있어요..."
          : "AI 독후감 생성하기"}

      </button>


      {/* ==================================================
          AI 독후감 결과
      ================================================== */}

      {generated && (

        <div className="result-card">

          <div className="result-title">
            ✨ AI 독후감
          </div>


          <div className="result-content">
            {generatedReview}
          </div>

        </div>

      )}

    </div>

  );

}


export default AIWrite;
